import{_ as i,l as d,o as a,c as n,v as o,p as c,x as t,d as l,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"整数溢出","description":"","frontmatter":{"title":"整数溢出","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/integer-overflow.md","filePath":"cs/integer-overflow.md","lastUpdated":1789023840000}'),p={name:"cs/integer-overflow.md"};function A(h,e,B,_,m,f){const r=d("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="整数溢出" tabindex="-1">整数溢出 <a class="header-anchor" href="#整数溢出" aria-label="Permalink to &quot;整数溢出&quot;">​</a></h1><div class="epigraph"><p>无符号运算在模 $2^n$ 上闭合；有符号溢出不在这个闭合里——标准把它留给未定义行为，而不是留给「绕回」。</p><footer>—— 据 ISO/IEC 9899；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/undefined-behavior">未定义行为</a>把「离开抽象机器」收成总规则。本课不重列附录 J，也不从比特编码另起——补码怎么排是信息课的缺口。缺口是：日常加减看起来像数学整数，<strong>C 的 <code>int</code> 与 <code>unsigned</code> 在越界时走的不是同一条规则</strong>。把两条混成「都会 wrap」，优化器会删掉你的溢出检查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机器字宽有限。无符号类型的加减乘在标准里定义为模 \\(2^n\\)，绕回是语义，不是事故。有符号类型的溢出是 UB：实现可以绕回，也可以陷入，也可以让编译器假设「有符号加减永不溢出」从而把 <code>if (a + 1 &lt; a)</code> 整段删掉。缺口因此不是「整数有范围」，而是<strong>哪一种溢出仍有定义</strong>。前面栈与数组课里的下标计算，很多从这里开始悄悄变成 UB。</p><p>本课只谈 C 的整数类型在表达式中的溢出。移位、除零、从无符号到有符号的转换另有规则，点到为止：负值右移是实现定义；移位位数不小于宽度是 UB。后课信息与离散会把补码表示讲清；这里先把语言契约钉死，避免用「硬件会 wrap」去写源码。</p><h3 id="无符号绕回不是「更安全」" tabindex="-1">无符号绕回不是「更安全」 <a class="header-anchor" href="#无符号绕回不是「更安全」" aria-label="Permalink to &quot;无符号绕回不是「更安全」&quot;">​</a></h3><p>模运算有定义，不表示逻辑正确。长度相减得到巨大的 <code>size_t</code>、分配尺寸绕回，是真实漏洞模式。有符号用更宽类型或先检查再运算；无符号要用模的代数来想，而不是当成不会错的自然数。也不要把 <code>char</code> 默认有符号当成可移植事实——那是实现定义。</p><p><span class="marginnote">CSAPP 第 2 章用模 \\(2^w\\) 讲无符号与补码算术，并强调 C 对有符号溢出的处理与硬件指令不必相同。ISO C 把无符号规定为绕回，把有符号溢出规定为 UB，正是为了让优化器利用「数学整数」的不等式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先看操作数在整数提升与常规算术转换之后的类型，再判断是否无符号。需要可移植的溢出检查时：对无符号，用模前的不等式（如 <code>a &gt; UINT_MAX - b</code>）；对有符号，用更宽类型或标准库即将提供的检查接口，避免先算出已经溢出的结果再判断。循环下标用无符号时，倒数到 0 的 <code>--</code> 会绕回，终止条件要按模来写。</p>',11)),(a(),c(E,null,{default:t(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E6%95%B4%E6%95%B0%E8%BF%90%E7%AE%97%22%5D%20--%3E%20U%5B%22%E6%97%A0%E7%AC%A6%E5%8F%B7%EF%BC%9A%E6%A8%A1%202%20%E7%9A%84%20n%20%E6%AC%A1%E6%96%B9%22%5D%0A%20%20OP%20--%3E%20S%5B%22%E6%9C%89%E7%AC%A6%E5%8F%B7%EF%BC%9A%E6%BA%A2%E5%87%BA%E5%8D%B3%E6%9C%AA%E5%AE%9A%E4%B9%89%22%5D%0A%20%20S%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E5%8F%AF%E5%88%A0%E6%8E%89%E6%BA%A2%E5%87%BA%E5%88%86%E6%94%AF%22%5D%0A%20%20U%20--%3E%20WRAP%5B%22%E7%BB%95%E5%9B%9E%E6%98%AF%E8%AF%AD%E4%B9%89%EF%BC%8C%E4%BB%8D%E5%8F%AF%E8%83%BD%E9%80%BB%E8%BE%91%E9%94%99%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><code>size_t</code> 无符号。对象大小、数组长度相减优先用无符号规则思考。需要差值可能为负时，先转成有符号宽类型，并保证输入在范围内。</p><p>提升规则会在运算前把较小类型变成 <code>int</code>，于是 <code>uint16_t</code> 相乘可能在有符号 <code>int</code> 上溢出——这是语言，不是硬件字宽。写固定宽度算术时要先看运算在哪种类型上进行。后课悬挂会从「尺寸绕回导致分配过小、随后写爆」接过来。信息与离散课会把补码表示讲清；在那之前，本课禁止用「寄存器里反正 wrap」来为有符号 C 辩护。无符号绕回是模运算，要真当模来用，例如环形缓冲下标。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化器若允许假设有符号永不溢出，就可以把计数器递增写成更简单的归纳，把看似多余的范围检查当死代码。这与上一课的机制是同一件事，只是对象从指针换成了整数。无符号没有这条假设，所以同一套检查写成无符号时可能「恰好」留下；这不是风格胜利，是两类语义不同。</p><p>后课信息课会说明：硬件上有符号加法与无符号加法往往是同一条指令，只是标志位解释不同。语言选择把有符号溢出从这条指令的绕回里摘出去，是为了抽象机器，不是因为 ALU 算不了。</p><p>移位与乘积是同一契约的延伸：把长度算成字节数时 <code>n * sizeof *p</code> 若用有符号 <code>int</code> 装 <code>n</code>，乘法可能 UB，再传给 <code>malloc</code> 时已经离开语言。无符号包装会给出过小的分配尺寸，随后的写入越界——从溢出走进悬挂与越界两条后课。循环 <code>for (int i = 0; i &lt;= n; i++)</code> 在 <code>n == INT_MAX</code> 时也可能溢出。信息课将说明硬件上加减常常不分有无符号；本课要记住：语言在有符号一侧故意不认那条绕回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 IEEE 浮点溢出，那是数值课与 <a href="/cs/ieee-754">IEEE 754</a> 的事。也不把补码位型重推一遍。下一课<a href="/cs/lifetime-dangling">生命周期与悬挂</a>回到对象寿命。后课默认：无符号绕回有定义；有符号溢出是 UB；不能用一次硬件观察代替标准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无符号算术模 \\(2^n\\)；有符号溢出是未定义行为。</li><li>硬件绕回不能当作有符号 C 的语义。</li><li>长度与下标计算要先分清类型，再写检查。</li><li>下一课处理指针在对象死后仍被使用的问题。</li><li>出处：ISO C 整数语义；CSAPP 第 2 章；K&amp;R 类型与算术。</li></ul>',10))])}const P=i(p,[["render",A]]);export{C as __pageData,P as default};
